<?php
require __DIR__.'/bootstrap.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Soumission POST requise.');}
$paymentId=(int)($_POST['paiement_id']??0);
try{
 if(!hash_equals((string)($_SESSION['contract_pv_csrf']??''),(string)($_POST['_csrf']??'')))throw new RuntimeException('Session expirée. Rechargez le PV.');
 $pdo->beginTransaction();
 $q=$pdo->prepare("SELECT p.*,c.reference,c.statut contrat_statut,c.fournisseur_id,c.chantier_id,c.signataire_banamur_personnel_id,COALESCE(NULLIF(s.nom_commercial,''),s.raison_sociale,CONCAT(s.person_first_name,' ',s.person_last_name)) fournisseur_nom,s.telephone,r.signature_banamur,r.signature_sous_traitant FROM contrat_sous_traitance_paiement p JOIN contrat_sous_traitance c ON c.id=p.contrat_id JOIN fournisseur_banamur s ON s.id_fournisseur=c.fournisseur_id LEFT JOIN contrat_reception_pv r ON r.paiement_id=p.id WHERE p.id=? FOR UPDATE");$q->execute([$paymentId]);$payment=$q->fetch(PDO::FETCH_ASSOC);if(!$payment)throw new RuntimeException('Dossier de paiement contractuel introuvable.');
 $contractManager->assertPaymentEligible((int)$payment['contrat_id']);
 if(!empty($payment['fiche_id'])){$_SESSION['contract_feb_flash']='La FEB contractuelle existe déjà.';$pdo->rollBack();header('Location: voir.php?id='.(int)$payment['contrat_id']);exit;}
 if(empty($payment['signature_banamur'])||empty($payment['signature_sous_traitant']))throw new RuntimeException('Les deux signatures du PV sont obligatoires avant la soumission de la FEB.');
 if(empty($payment['facture_fne_path'])||!is_file(dirname(__DIR__).'/'.ltrim((string)$payment['facture_fne_path'],'/')))throw new RuntimeException('La facture FNE du dossier est absente ou inaccessible.');
 if((float)$payment['montant_net']<=0)throw new RuntimeException('Le montant net de la FEB doit être positif.');
 $q=$pdo->prepare('SELECT cl.ligne_devis_id FROM contrat_sous_traitance_ligne cl WHERE cl.contrat_id=? ORDER BY cl.id LIMIT 1');$q->execute([(int)$payment['contrat_id']]);$lineId=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT ldb.id FROM ligne_debourse_banamur ldb JOIN debourse_banamur db ON db.id=ldb.debourse_id WHERE db.ligne_devis_id=? ORDER BY ldb.id LIMIT 1');$q->execute([$lineId]);$debitLineId=(int)$q->fetchColumn();if(!$debitLineId)throw new RuntimeException('Aucune ligne de déboursé n’est disponible pour rattacher cette FEB.');
 do{$num='FD-'.date('ym').'-'.str_pad((string)random_int(1,99999),5,'0',STR_PAD_LEFT);$q=$pdo->prepare('SELECT COUNT(*) FROM fiche_decaissement WHERE num_fiche=?');$q->execute([$num]);}while((int)$q->fetchColumn()>0);
 $typeLabel=['acompte'=>'Acompte d’exécution','avancement'=>'Paiement sur avancement '.number_format((float)$payment['avancement_cumule'],2,',',' ').' %','solde'=>'Solde contractuel'][$payment['type_paiement']]??'Paiement contractuel';$details='FEB contractuelle '.$payment['reference'].' — '.$typeLabel;$pvPath='contrats/pv.php?paiement_id='.$paymentId.'&download=1';
 $q=$pdo->prepare("INSERT INTO fiche_decaissement(num_fiche,beficiaire_fiche,montant_fiche,tel_beneficiaire_fiche,fournisseur_id,fournisseur_nom,chantier_id,ligne_debourse_id,designation_fiche,precision_fiche,details_demande,mode_paiement,date_creat_fiche,created_by_user_id,contract_id,contract_payment_id,contract_payment_type,contract_progress_rate,contract_pv_path,contract_fne_path,facture_reference,pv_reception_reference,conforme,approuve,etat_fiche,decaisse,otp_valide,sauvegarder) VALUES(?,?,?,?,?,?,?,?,?,?,?,'Virement bancaire',NOW(),?,?,?,?,?,?,?,?,?,0,0,0,0,0,0)");
 $q->execute([$num,$payment['fournisseur_nom'],(float)$payment['montant_net'],$payment['telephone'],(int)$payment['fournisseur_id'],$payment['fournisseur_nom'],(int)$payment['chantier_id'],$debitLineId,'Contrat '.$payment['reference'],$payment['type_paiement'],$details,(int)($_SESSION['user_id']??0),(int)$payment['contrat_id'],$paymentId,$payment['type_paiement'],(float)$payment['avancement_cumule'],$pvPath,$payment['facture_fne_path'],$payment['facture_fne_path'],$pvPath]);$ficheId=(int)$pdo->lastInsertId();
 $q=$pdo->prepare("UPDATE contrat_sous_traitance_paiement SET fiche_id=?,pv_path=?,statut_financier='en_circuit' WHERE id=?");$q->execute([$ficheId,$pvPath,$paymentId]);$pdo->commit();
 $_SESSION['contract_feb_flash']='FEB '.$num.' créée et transmise dans le circuit normal de conformité, validation et décaissement.';header('Location: voir.php?id='.(int)$payment['contrat_id']);exit;
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['contract_feb_error']=$e->getMessage();header('Location: reception.php?paiement_id='.$paymentId);exit;}
